  \label{lem:pullback_moduleTensorPow}
  \lean{AlgebraicGeometry.Scheme.Modules.pullback_moduleTensorPow_iso}
  \uses{def:sheafTensorObj, def:sheafTensorPow, def:sheafModuleTwist,
